struct Configuration {PhyConfiguration phy;PairedOptions paired;unsigned repair_candidates=24,xor_mask=0;bool status_fields=false;};
Json integer(const char* key,unsigned value,unsigned low,unsigned high){return {{"key",key},{"type","integer"},{"extension",true},{"label_key",key},{"default",value},{"minimum",low},{"maximum",high}};}
Json boolean(const char* key,bool value){return {{"key",key},{"type","boolean"},{"extension",true},{"label_key",key},{"default",value}};}
Json ownFields(){return Json::array({integer("paired_body_bytes",48,2,248),integer("paired_zero_code",1,1,2),integer("paired_crc_initial",0x0399,0,65535),integer("paired_crc_xorout",0,0,65535),boolean("paired_repair",false),integer("paired_maximum_erasures",12,0,16),integer("paired_repair_candidates",24,1,32),integer("paired_maximum_trials",131072,1,1048576),integer("paired_payload_xor",0,0,255),boolean("paired_status_fields",false)});}
Json describePaired(const RecoveryContext& context,const Json& supplied){auto fields=phy_descriptions(context,supplied);for(auto& field:fields){const auto key=field.at("key").get<std::string>();if(key=="sf")field["default"]=11;if(key=="bandwidth_hz")field["default"]=std::min(500000u,context.analysis->sample_rate());}for(auto field:ownFields()){if(field.at("key")=="paired_maximum_erasures" || field.at("key")=="paired_repair_candidates" || field.at("key")=="paired_maximum_trials"){field["enabled_when"]={{"key","paired_repair"},{"equals",true}};field["inactive_allowed"]=true;}fields.push_back(std::move(field));}return fields;}
Configuration parsePaired(const RecoveryContext& context,const Json& supplied) {
    Configuration config;Json phy=Json::object(),values=Json::object();const auto descriptions=describePaired(context,supplied);std::set<std::string> own;
    for(const auto& field:ownFields())own.insert(field.at("key").get<std::string>());
    for(const auto& field:descriptions){const auto key=field.at("key").get<std::string>();if(own.contains(key))values[key]=supplied.value(key,field.at("default"));else phy[key]=supplied.value(key,field.at("default"));}
    for(const auto& [key,value]:supplied.items())if(!own.contains(key) && !phy.contains(key))phy[key]=value;
    config.phy=parse_phy(context,phy);const auto issue=[&](const char* key){config.phy.failure.issues.push_back({{"field",key},{"label_key","paired.issue.parameter"}});};
    for(const auto& field:ownFields()){const auto key=field.at("key").get<std::string>();const auto& value=values.at(key);const auto valid=field.at("type")=="boolean"?value.is_boolean():value.is_number_integer() && value>=field.at("minimum") && value<=field.at("maximum");if(!valid)issue(key.c_str());}
    if(!config.phy.failure.issues.empty())return config;
    config.paired.body_bytes=values.at("paired_body_bytes");config.paired.zero_pair=values.at("paired_zero_code");config.paired.crc_initial=values.at("paired_crc_initial");config.paired.crc_xorout=values.at("paired_crc_xorout");config.paired.repair=values.at("paired_repair");config.paired.maximum_erasure_pairs=values.at("paired_maximum_erasures");config.paired.maximum_trials=values.at("paired_maximum_trials");config.repair_candidates=values.at("paired_repair_candidates");config.xor_mask=values.at("paired_payload_xor");config.status_fields=values.at("paired_status_fields");if(config.paired.body_bytes%2)issue("paired_body_bytes");if(config.status_fields && config.paired.body_bytes!=48)issue("paired_status_fields");config.phy.parameters.update(values);return config;
}
std::vector<RecoveryValue> bytesOf(const Hypothesis& candidate,unsigned count){std::vector<RecoveryValue> bytes;bytes.reserve(count);for(unsigned i=0;i<std::min(count,candidate.byte_count);++i){RecoveryValue value;value.value=candidate.bytes[i];value.known=candidate.known[i];bytes.push_back(std::move(value));}return bytes;}
std::vector<RecoveryValue> bytesOf(const Packet& packet,unsigned count){std::vector<RecoveryValue> bytes;bytes.reserve(count);for(unsigned i=0;i<std::min<std::size_t>(count,packet.bytes.size());++i){RecoveryValue value;value.value=packet.bytes[i].value;value.known=packet.bytes[i].known;bytes.push_back(std::move(value));}return bytes;}
struct Accepted {PairSolution solution;Hypothesis hypothesis;};
bool same(const PairSolution& a,const PairSolution& b){return a.wire_count==b.wire_count && std::equal(a.wire.begin(),a.wire.begin()+a.wire_count,b.wire.begin());}
void append(RecoverySequence& sequence,unsigned value,bool known,const char* issue,std::vector<RecoveryLink> inputs){RecoveryValue item;item.value=value;item.known=known;item.issue_key=issue;item.inputs=std::move(inputs);sequence.values.push_back(std::move(item));}
std::string hex(std::span<const std::uint8_t> bytes){constexpr char digits[]="0123456789ABCDEF";std::string value;for(const auto byte:bytes){value+=digits[byte>>4];value+=digits[byte&15];}return value;}
